async(page)=>{
 const checks=[];const check=(ok,text)=>{if(!ok)throw Error(text);checks.push(text)};
 const add=async name=>{await page.getByRole('button',{name:'Add a component',exact:true}).click();await page.getByRole('button',{name,exact:true}).click()};
 await add('Presentation');
 await page.getByRole('textbox',{name:'Slide text 1',exact:true}).fill('A shared direction');
 await page.getByRole('button',{name:'Next slide',exact:true}).click();
 await page.reload();
 await page.getByRole('button',{name:'Previous slide',exact:true}).click();
 check(await page.getByRole('textbox',{name:'Slide text 1',exact:true}).innerText()==='A shared direction','Local slide text edits survive navigation and reload');
 await page.getByRole('button',{name:'History',exact:true}).click();await page.getByText('Read this version',{exact:true}).first().click();
 check((await page.locator('.history-entry pre').first().innerText()).includes('A shared direction'),'Slide history contains the saved narrative');
 await page.getByRole('button',{name:'Close Untitled presentation',exact:true}).click();
 await page.getByRole('button',{name:'Add a component',exact:true}).click();
 const fixture=await page.request.get(page.url().split(/[?#]/)[0].replace(/[^/]*$/, '')+'tests/fixtures/working-plan.xlsx');if(!fixture.ok())throw Error('Workbook fixture unavailable');await page.locator('#composer-import').setInputFiles({name:'working-plan.xlsx',mimeType:'application/octet-stream',buffer:await fixture.body()});
 await page.getByRole('gridcell',{name:'B2',exact:true}).click();
 await page.getByRole('textbox',{name:'Formula bar',exact:true}).fill('25');
 await page.getByRole('textbox',{name:'Formula bar',exact:true}).press('Enter');
 const camera=await page.locator('#world').getAttribute('style'),grid=await page.locator('.sheet-scroll').boundingBox();
 await page.mouse.move(grid.x+grid.width/2,grid.y+grid.height/2);await page.mouse.wheel(0,250);
 await page.waitForFunction(()=>document.querySelector('.sheet-scroll').scrollTop>0);
 check(await page.locator('#world').getAttribute('style')===camera,'Scrolling a worksheet does not accidentally pan the canvas');
 await page.getByRole('button',{name:'History',exact:true}).click();await page.getByText('Read this version',{exact:true}).first().click();
 check((await page.locator('.history-entry pre').first().innerText()).includes('B2: 25'),'Workbook history contains actual saved cells');
 await page.getByRole('button',{name:'Context graph',exact:true}).click();
 await page.locator('[data-node="resources:private"]').press('Enter');
 await page.getByRole('button',{name:'Inspect working-plan.xlsx',exact:true}).press('Enter');
 await page.getByRole('gridcell',{name:'B2',exact:true}).click();
 check(await page.getByRole('textbox',{name:'Cell address',exact:true}).inputValue()==='B2','Graph-local cell selection survives an inspector redraw');
 await page.getByRole('textbox',{name:'Formula bar',exact:true}).fill('30');await page.getByRole('textbox',{name:'Formula bar',exact:true}).press('Enter');
 check(await page.getByRole('gridcell',{name:'B5',exact:true}).innerText()==='72','Graph-local workbook edits recalculate dependent cells');
 await page.getByRole('button',{name:'Assumptions',exact:true}).click();
 check(await page.getByRole('gridcell',{name:'A2',exact:true}).innerText()==='Working days','Graph-local worksheet navigation retains its selection');
 await page.getByRole('button',{name:'Studio',exact:true}).click();
 await page.getByRole('button',{name:'Context graph',exact:true}).click();await add('Project');
 await page.getByRole('button',{name:'Knowledge',exact:true}).click();
 check(await page.getByRole('button',{name:/Project instructions/}).count()===1,'Graph-local project tabs retain their state');
 await page.getByRole('button',{name:/Project instructions/}).click();
 check(await page.locator('.knowledge-reading').count()===1&&await page.locator('.module').count()===1,'Project instructions open in the existing graph surface');
 await page.getByRole('button',{name:'Back to knowledge',exact:true}).click();
 check(await page.getByRole('button',{name:/Project instructions/}).count()===1,'Return from project instructions restores Knowledge in place');
 return checks;
}
